import catalogJson from '../../content/catalog.json';
import type { CatalogEntry, Song } from './song';

/** Built-in songs, generated by `npm run content`. Each song JSON is its own lazy chunk. */
export const catalog = catalogJson as CatalogEntry[];

const loaders = import.meta.glob<Song>('../../content/build/*.json', { import: 'default' });

export async function loadSong(id: string): Promise<Song> {
  const load = loaders[`../../content/build/${id}.json`];
  if (!load) throw new Error(`Música não encontrada: ${id}`);
  return load();
}
